#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>
int main(int argc, char** argv) {
    long long n = 0;
    if (argc > 1) n = atoll(argv[1]);
    if (n < 0) n = 0;
    std::vector<int> a, b, c;
    a.push_back(1);
    b.push_back(1);
    for (long long i = 0; i < n; i++) {
        size_t m = a.size() > b.size() ? a.size() : b.size();
        c.assign(m, 0);
        int carry = 0;
        for (size_t j = 0; j < m; j++) {
            int s = carry;
            if (j < a.size()) s += a[j];
            if (j < b.size()) s += b[j];
            c[j] = s % 10;
            carry = s / 10;
        }
        if (carry) c.push_back(carry);
        a = b;
        b = c;
    }
    std::string out;
    for (size_t j = a.size(); j-- > 0;) out += (char)('0' + a[j]);
    printf("%s\n", out.c_str());
    return 0;
}
// */ */
//\
fn main() { //\
    let args: Vec<String> = std::env::args().collect(); //\
    let n: u64 = if args.len() > 1 { args[1].trim().parse().unwrap_or(0) } else { 0 }; //\
    let mut a: Vec<u8> = vec![1]; //\
    let mut b: Vec<u8> = vec![1]; //\
    for _ in 0..n { //\
        let m = if a.len() > b.len() { a.len() } else { b.len() }; //\
        let mut c: Vec<u8> = Vec::with_capacity(m + 1); //\
        let mut carry: u8 = 0; //\
        for j in 0..m { //\
            let mut s: u8 = carry; //\
            if j < a.len() { s += a[j]; } //\
            if j < b.len() { s += b[j]; } //\
            c.push(s % 10); //\
            carry = s / 10; //\
        } //\
        if carry > 0 { c.push(carry); } //\
        a = b; //\
        b = c; //\
    } //\
    let s: String = a.iter().rev().map(|d| (b'0' + *d) as char).collect(); //\
    println!("{}", s); //\
} //\
// end

